INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `BroadcastTextId`) VALUES (189602, 0, 0, 'Pleased to meet ya!', 12, 0, 100.0, 0, 0, 224861) ON DUPLICATE KEY UPDATE `Text`=VALUES(`Text`), `Type`=VALUES(`Type`);
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `BroadcastTextId`) VALUES (189602, 0, 1, 'Spotted some promisin'' crew members as I was flyin'' over the city. Round ''em up and let''s get to it!', 12, 0, 100.0, 0, 0, 225059) ON DUPLICATE KEY UPDATE `Text`=VALUES(`Text`), `Type`=VALUES(`Type`);
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `BroadcastTextId`) VALUES (189600, 0, 0, 'Many are near Stormwind Harbor, where our next journey awaits. This portal will help take you there.', 12, 0, 100.0, 0, 0, 0) ON DUPLICATE KEY UPDATE `Text`=VALUES(`Text`), `Type`=VALUES(`Type`);
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `BroadcastTextId`) VALUES (189767, 0, 0, 'New adventures? I''m game. When there''s work tae be done, my hammer''s always ready tae be put tae good use! See ye at the docks!', 12, 0, 100.0, 0, 0, 224956) ON DUPLICATE KEY UPDATE `Text`=VALUES(`Text`), `Type`=VALUES(`Type`);
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `BroadcastTextId`) VALUES (189765, 0, 0, 'A-hem. Duty calls! Now if you''ll excuse me, I must be off to make a name for myself in the splendiferous Dragon Isles!', 12, 0, 100.0, 0, 0, 224954) ON DUPLICATE KEY UPDATE `Text`=VALUES(`Text`), `Type`=VALUES(`Type`);
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `BroadcastTextId`) VALUES (198401, 0, 0, 'The dracthyr stand ready.', 12, 0, 100.0, 0, 0, 216925) ON DUPLICATE KEY UPDATE `Text`=VALUES(`Text`), `Type`=VALUES(`Type`);
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `BroadcastTextId`) VALUES (142641, 0, 0, 'The boat to Kul Tiras has just arrived. All aboard for Boralus!', 14, 0, 100.0, 0, 0, 160728) ON DUPLICATE KEY UPDATE `Text`=VALUES(`Text`), `Type`=VALUES(`Type`);
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `BroadcastTextId`) VALUES (189569, 0, 1, 'While you make preparations to board your vessel, I shall fly on ahead. Do try not to get seasick, $n!', 12, 0, 100.0, 0, 0, 0) ON DUPLICATE KEY UPDATE `Text`=VALUES(`Text`), `Type`=VALUES(`Type`);
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `BroadcastTextId`) VALUES (194652, 0, 0, 'Keep it going, We need a complete survey of the eastern coastline.', 12, 0, 100.0, 0, 0, 0) ON DUPLICATE KEY UPDATE `Text`=VALUES(`Text`), `Type`=VALUES(`Type`);
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `BroadcastTextId`) VALUES (194652, 0, 1, 'Keep it going, We need a complete survey of the eastern coastline.', 12, 0, 100.0, 0, 0, 0) ON DUPLICATE KEY UPDATE `Text`=VALUES(`Text`), `Type`=VALUES(`Type`);
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `BroadcastTextId`) VALUES (195830, 0, 0, 'Help!!!', 14, 0, 100.0, 0, 0, 0) ON DUPLICATE KEY UPDATE `Text`=VALUES(`Text`), `Type`=VALUES(`Type`);
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `BroadcastTextId`) VALUES (193914, 0, 0, 'Just a few more whacks!', 12, 0, 100.0, 0, 0, 0) ON DUPLICATE KEY UPDATE `Text`=VALUES(`Text`), `Type`=VALUES(`Type`);
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `BroadcastTextId`) VALUES (188296, 0, 0, 'Not... like... this...', 12, 0, 100.0, 0, 0, 0) ON DUPLICATE KEY UPDATE `Text`=VALUES(`Text`), `Type`=VALUES(`Type`);
